    "inlineSchema": "// =============================================================================\n// MotoGuard IoT — Prisma Schema (PostgreSQL)\n// =============================================================================\n// Tabelas:\n//   · motorcycle_profiles — Classes de mota (Scooter, Naked, etc.) + limiares\n//   · users               — Utilizadores da plataforma\n//   · motorcycles         — Motas associadas a cada utilizador\n//   · trips               — Viagens registadas\n//   · trip_events         — Eventos de risco detetados durante viagens\n// =============================================================================\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../backend/src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─── Utilizadores ───────────────────────────────────────────────────────────\nmodel User {\n  id           String   @id @default(uuid())\n  email        String   @unique\n  passwordHash String   @map(\"password_hash\")\n  name         String\n  resetToken   String?  @map(\"reset_token\") // Token para reset de senha\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  motorcycles Motorcycle[]\n  trips       Trip[]\n\n  @@map(\"users\")\n}\n\n// ─── Perfis / Classes de Mota ───────────────────────────────────────────────\n// Dados de referência semeados a partir de config.py (8 perfis).\n// Contém os limiares físicos e thresholds de deteção de eventos.\nmodel MotorcycleProfile {\n  id                  String   @id @default(uuid())\n  name                String   @unique // \"Scooter\", \"Naked\", etc.\n  example             String? // \"Honda PCX 125, Yamaha XMAX 300\"\n  // ─── Limites do modelo ──────────────────────────\n  ccMin               Int      @map(\"cc_min\") // cilindrada mínima\n  ccMax               Int      @map(\"cc_max\") // cilindrada máxima\n  maxSpeedKmh         Int      @map(\"max_speed_kmh\")\n  maxRpm              Int      @map(\"max_rpm\")\n  engineTempMin       Int      @map(\"engine_temp_min\") // °C\n  engineTempMax       Int      @map(\"engine_temp_max\") // °C\n  voltageMin          Float    @map(\"voltage_min\")\n  voltageMax          Float    @map(\"voltage_max\")\n  typicalMaxRollDeg   Int      @map(\"typical_max_roll_deg\")\n  avgWeightKg         Int      @map(\"avg_weight_kg\")\n  // ─── Thresholds de deteção ──────────────────────\n  crashRollThreshold  Int      @map(\"crash_roll_threshold\") // °\n  crashPitchThreshold Int      @map(\"crash_pitch_threshold\") // °\n  crashGForce         Float    @map(\"crash_g_force\") // G\n  crashConfirmSec     Int      @map(\"crash_confirm_sec\") // segundos\n  criticalRpm         Int      @map(\"critical_rpm\")\n  criticalTemp        Int      @map(\"critical_temp\") // °C\n  criticalVoltage     Float    @map(\"critical_voltage\") // V\n  createdAt           DateTime @default(now()) @map(\"created_at\")\n\n  motorcycles Motorcycle[]\n\n  @@map(\"motorcycle_profiles\")\n}\n\n// ─── Motas ──────────────────────────────────────────────────────────────────\nmodel Motorcycle {\n  id        String   @id @default(uuid())\n  userId    String   @map(\"user_id\")\n  profileId String?  @map(\"profile_id\") // referência ao perfil da classe\n  name      String // ex: \"A minha PCX\"\n  brand     String? // ex: \"Honda\", \"Yamaha\"\n  year      Int?\n  deviceId  String?  @map(\"device_id\") // ex: \"MOTOGUARD-SIM-01\"\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  user    User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  profile MotorcycleProfile? @relation(fields: [profileId], references: [id], onDelete: SetNull)\n  trips   Trip[]\n\n  @@map(\"motorcycles\")\n}\n\n// ─── Viagens ────────────────────────────────────────────────────────────────\nmodel Trip {\n  id           String     @id @default(uuid())\n  userId       String     @map(\"user_id\")\n  motorcycleId String     @map(\"motorcycle_id\")\n  source       TripSource @default(SIMULATOR)\n  startedAt    DateTime   @map(\"started_at\")\n  endedAt      DateTime?  @map(\"ended_at\")\n  distanceKm   Float?     @map(\"distance_km\")\n  maxSpeedKmh  Float?     @map(\"max_speed_kmh\")\n  avgSpeedKmh  Float?     @map(\"avg_speed_kmh\")\n  maxRollDeg   Float?     @map(\"max_roll_deg\")\n  maxGForce    Float?     @map(\"max_g_force\")\n  status       TripStatus @default(ACTIVE)\n  createdAt    DateTime   @default(now()) @map(\"created_at\")\n\n  user       User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  motorcycle Motorcycle  @relation(fields: [motorcycleId], references: [id], onDelete: Cascade)\n  events     TripEvent[]\n  gpxData    GpxData?\n\n  @@index([userId])\n  @@index([motorcycleId])\n  @@index([startedAt])\n  @@map(\"trips\")\n}\n\nenum TripStatus {\n  ACTIVE\n  COMPLETED\n  CANCELLED\n}\n\nenum TripSource {\n  SIMULATOR\n  GPX_IMPORTED\n  DEVICE_REAL\n}\n\n// ─── Eventos de Risco ───────────────────────────────────────────────────────\nmodel TripEvent {\n  id          String        @id @default(uuid())\n  tripId      String        @map(\"trip_id\")\n  type        EventType\n  severity    EventSeverity\n  message     String\n  latitude    Float?\n  longitude   Float?\n  speedKmh    Float?        @map(\"speed_kmh\")\n  rollDeg     Float?        @map(\"roll_deg\")\n  gForce      Float?        @map(\"g_force\")\n  engineTempC Float?        @map(\"engine_temp_c\")\n  voltage     Float?\n  occurredAt  DateTime      @map(\"occurred_at\")\n  createdAt   DateTime      @default(now()) @map(\"created_at\")\n\n  trip Trip @relation(fields: [tripId], references: [id], onDelete: Cascade)\n\n  @@index([tripId])\n  @@index([type])\n  @@index([severity])\n  @@index([occurredAt])\n  @@map(\"trip_events\")\n}\n\n// ─── Dados GPX Importados ───────────────────────────────────────────────────\nmodel GpxData {\n  id         String   @id @default(uuid())\n  tripId     String   @unique @map(\"trip_id\") // Um-para-um com Trip\n  filename   String // Nome original do ficheiro\n  fileSize   Int      @map(\"file_size\") // Tamanho em bytes\n  waypoints  Json // Array de pontos {lat, lon, ele, time}\n  bounds     Json // {minLat, maxLat, minLon, maxLon}\n  totalTime  Int?     @map(\"total_time\") // Duração em segundos\n  importDate DateTime @default(now()) @map(\"import_date\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n\n  trip Trip @relation(fields: [tripId], references: [id], onDelete: Cascade)\n\n  @@map(\"gpx_data\")\n}\n\nenum EventType {\n  HARD_BRAKING // Travagem brusca\n  EXCESSIVE_LEAN // Inclinação excessiva\n  HIGH_VIBRATION // Vibração anómala\n  OVERHEAT // Sobreaquecimento do motor\n  LOW_VOLTAGE // Voltagem baixa / falha de alternador\n  CRASH_DETECTED // Queda detetada\n  RAPID_ACCELERATION // Aceleração brusca\n  TIRE_PRESSURE_LOW // Pressão dos pneus baixa\n  OIL_PRESSURE_LOW // Pressão do óleo baixa\n}\n\nenum EventSeverity {\n  INFO\n  WARNING\n  CRITICAL\n}\n",
